import{_ as a,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/linear-area-logic.svg",g=JSON.parse('{"title":"奥数精讲：直线型面积计算（图形的解构）","description":"掌握直线型组合图形面积的计算方法，学习分割、补全和平移三大核心技巧，让不规则图形的面积计算变得简单直观。","frontmatter":{"title":"奥数精讲：直线型面积计算（图形的解构）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["面积计算","切割填充","平移法"],"description":"掌握直线型组合图形面积的计算方法，学习分割、补全和平移三大核心技巧，让不规则图形的面积计算变得简单直观。"},"headers":[],"relativePath":"posts/primary-math-olympiad-linear-area.md","filePath":"posts/primary-math-olympiad-linear-area.md","lastUpdated":null}'),e={name:"posts/primary-math-olympiad-linear-area.md"};function l(r,s,o,c,i,h){return n(),m("div",null,[...s[0]||(s[0]=[t('<h1 id="直线型面积计算-拆解与重组的智慧" tabindex="-1">直线型面积计算：拆解与重组的智慧 <a class="header-anchor" href="#直线型面积计算-拆解与重组的智慧" aria-label="Permalink to &quot;直线型面积计算：拆解与重组的智慧&quot;">​</a></h1><p>在小学奥数中，我们经常会遇到一些由长方形、正方形组合而成的不规则图形（直线型图形）。解决这些问题的关键不在于死记硬背公式，而在于如何通过<strong>切割</strong>、<strong>填充</strong>或<strong>平移</strong>，将其转化为我们熟悉的标准图形。</p><hr><h2 id="一、-三大核心解题策略" tabindex="-1">一、 三大核心解题策略 <a class="header-anchor" href="#一、-三大核心解题策略" aria-label="Permalink to &quot;一、 三大核心解题策略&quot;">​</a></h2><h3 id="_1-分割法-化整为零" tabindex="-1">1. 分割法（化整为零） <a class="header-anchor" href="#_1-分割法-化整为零" aria-label="Permalink to &quot;1. 分割法（化整为零）&quot;">​</a></h3><p>将一个复杂的图形分割成几个简单的长方形或正方形，分别计算它们的面积再相加。</p><ul><li><strong>技巧：</strong> 寻找图形的“拐角”处作为切割点。</li></ul><h3 id="_2-补全法-借花献佛" tabindex="-1">2. 补全法（借花献佛） <a class="header-anchor" href="#_2-补全法-借花献佛" aria-label="Permalink to &quot;2. 补全法（借花献佛）&quot;">​</a></h3><p>将不规则图形补成一个大的规则图形，算出大图形的面积后再减去补上去的那部分。</p><ul><li><strong>适用场景：</strong> 图形有一个明显的“缺口”时。</li></ul><h3 id="_3-平移法-移花接木" tabindex="-1">3. 平移法（移花接木） <a class="header-anchor" href="#_3-平移法-移花接木" aria-label="Permalink to &quot;3. 平移法（移花接木）&quot;">​</a></h3><p>利用图形的对称性或通过平移线段，将复杂的边缘转化为简单的边界。</p><ul><li><strong>注意：</strong> 平移法在求“周长”时最为神奇，但在求面积时要小心面积守恒。</li></ul><p><img src="'+p+'" alt="直线型面积解题技巧"></p><hr><h2 id="二、-引导性思考-如何选择最优方法" tabindex="-1">二、 引导性思考：如何选择最优方法？ <a class="header-anchor" href="#二、-引导性思考-如何选择最优方法" aria-label="Permalink to &quot;二、 引导性思考：如何选择最优方法？&quot;">​</a></h2><p>面对一个图形，你应该先怎么想？</p><ol><li><strong>看外观：</strong> 如果图形有很多伸出来的部分，适合用<strong>分割法</strong>。</li><li><strong>看缺口：</strong> 如果图形像是一个大方块被挖掉了一块，适合用<strong>补全法</strong>。</li><li><strong>看辅助线：</strong> 能不能画一条线，让左右两边看起来一样？（利用对称）</li></ol><hr><h2 id="三、-引申思考-面积守恒与周长变化" tabindex="-1">三、 引申思考：面积守恒与周长变化 <a class="header-anchor" href="#三、-引申思考-面积守恒与周长变化" aria-label="Permalink to &quot;三、 引申思考：面积守恒与周长变化&quot;">​</a></h2><p>这是一个经典的坑：</p><ul><li><strong>面积守恒：</strong> 如果你只是把图形切割后重新拼凑，总面积是不变的。</li><li><strong>周长变化：</strong> 切割后再拼凑，或者平移线段，周长往往会发生变化！在计算时务必分清题目求的是面积还是周长。</li></ul><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习：</strong> 一个 L 型图形，横向底边长 10cm，纵向左边长 8cm，拐角处凹进去的部分长宽分别为 4cm 和 3cm。求它的面积。 <em>提示：尝试用分割法或补全法。</em></p></li><li><p><strong>进阶练习：</strong> 两个正方形拼在一起，大正方形边长 6cm，小正方形边长 4cm。求组合图形的周长和面积。 <em>提示：面积直接相加；周长要注意重合的那条边。</em></p></li><li><p><strong>挑战练习：</strong> 一个楼梯形图形，共有 5 级台阶，每级台阶的高是 2cm，宽是 3cm。求这个图形的总面积。 <em>提示：可以看作 5 个不同大小的长方形叠在一起，或者利用平移补全成一个大矩形。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>补全法：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>×</mo><mn>8</mn><mo>−</mo><mn>4</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>8</mn><mn>0</mn><mo>−</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>6</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">10 \\times 8 - 4 \\times 3 = 80 - 12 = 68</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">8</span></span></span></span> cm²。</li><li>面积：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mn>6</mn><mn>2</mn></msup><mo>+</mo><msup><mn>4</mn><mn>2</mn></msup><mo>=</mo><mn>3</mn><mn>6</mn><mo>+</mo><mn>1</mn><mn>6</mn><mo>=</mo><mn>5</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">6^2 + 4^2 = 36 + 16 = 52</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathrm">6</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathrm">4</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">2</span></span></span></span> cm²。周长：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>6</mn><mo>+</mo><mn>4</mn><mo>)</mo><mo>×</mo><mn>2</mn><mo>+</mo><mn>6</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">(6+4) \\times 2 + 6 \\times 2 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span> cm (或者 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>6</mn><mo>+</mo><mn>4</mn><mo>×</mo><mn>4</mn><mo>−</mo><mn>4</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">4 \\times 6 + 4 \\times 4 - 4 \\times 2 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span>)。</li><li>面积：可以分割为底 3 高 2, 底 6 高 2... 或者 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mo>(</mo><mn>2</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>6</mn><mo>+</mo><mn>8</mn><mo>+</mo><mn>1</mn><mn>0</mn><mo>)</mo><mo>=</mo><mn>3</mn><mo>×</mo><mn>3</mn><mn>0</mn><mo>=</mo><mn>9</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">3 \\times (2+4+6+8+10) = 3 \\times 30 = 90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">0</span></span></span></span> cm²。 或者看作：第 1 列 1 个小矩形，第 2 列 2 个... 总共 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>3</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">1+2+3+4+5=15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span> 个小矩形。每个面积 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">2 \\times 3 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>。总面积 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>×</mo><mn>6</mn><mo>=</mo><mn>9</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">15 \\times 6 = 90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">0</span></span></span></span> cm²。</li></ol>',28)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
